import { build } from 'esbuild';
import { mkdir, readFile, writeFile, copyFile } from 'node:fs/promises';
await mkdir('dist', {recursive:true});
await build({entryPoints:['src/app.ts'],outfile:'dist/app.js',bundle:true,minify:true,format:'esm',target:'es2022'});
await copyFile('public/index.html','dist/index.html');
const [html, js, snapshot]=await Promise.all([
  readFile('public/index.html','utf8'),
  readFile('dist/app.js','utf8'),
  readFile('data/region_snapshot.json','utf8'),
]);
await writeFile('src/assets.generated.ts',
  '/* Generated by npm run build. Do not edit manually. */\n' +
  'export const HTML=' + JSON.stringify(html) + ';\n' +
  'export const APP=' + JSON.stringify(js) + ';\n' +
  'export const SNAPSHOT=' + JSON.stringify(snapshot) + ';\n'
);
await build({entryPoints:['src/worker.ts'],outfile:'dist/worker.mjs',bundle:true,minify:true,format:'esm',target:'es2022',platform:'browser'});
